# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HUCURÂT SURESİ KİMLİK KARTI VE TEMEL İLKELERİ</text>\n  <rect x="35" y="55" width="280" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="175" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hucurât Suresi\'nin Özellikleri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Mushaf Sırası: 49. Sure</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• İniş Dönemi: Medine Dönemi (Medenî)</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• Ayet Sayısı: 18 Ayet</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• Adının Anlamı: \'Odalar\' (4. ayet)</text>\n  <text x="55" y="208" font-size="11.5" font-weight="bold" fill="#1e40af">• Unvanı: \'Ahlak ve Edep Suresi\'</text>\n  <rect x="335" y="55" width="330" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="500" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Toplumsal Barış ve İletişim İlkeleri</text>\n  <text x="355" y="108" font-size="11.5" fill="#334155">• 1-5. Ayetler: Hz. Peygamber\'e saygı ve nezaket</text>\n  <text x="355" y="132" font-size="11.5" fill="#334155">• 6. Ayet: Haberin doğruluğunu araştırma (فَتَبَيَّنُوا)</text>\n  <text x="355" y="156" font-size="11.5" fill="#334155">• 9-10. Ayetler: Müminlerin kardeşliği ve ıslah</text>\n  <text x="355" y="180" font-size="11.5" fill="#334155">• 11-12. Ayetler: Alay, lakap, zan, tecessüs, gıybet</text>\n  <text x="355" y="208" font-size="11.5" font-weight="bold" fill="#166534">• 13. Ayet: Evrensel eşitlik ve Takva ölçüsü</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HUCURÂT SURESİ 11-12. AYETLERDE YASAKLANAN 5 DAVRANIŞ</text>\n  <rect x="25" y="60" width="122" height="175" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="86" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">1. İSTİHZA</text>\n  <text x="86" y="112" text-anchor="middle" font-size="11" fill="#334155">(Alay Etmek)</text>\n  <text x="86" y="142" text-anchor="middle" font-size="10.5" fill="#475569">İnsanları küçük</text>\n  <text x="86" y="160" text-anchor="middle" font-size="10.5" fill="#475569">görüp onlarla</text>\n  <text x="86" y="178" text-anchor="middle" font-size="10.5" fill="#475569">eğlenmek.</text>\n  <rect x="157" y="60" width="122" height="175" rx="8" fill="#fff7ed" stroke="#f97316"/>\n  <text x="218" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#c2410c">2. KÖTÜ LAKAP</text>\n  <text x="218" y="112" text-anchor="middle" font-size="11" fill="#334155">(Tenâbüz)</text>\n  <text x="218" y="142" text-anchor="middle" font-size="10.5" fill="#475569">Kişiyi üzecek ve</text>\n  <text x="218" y="160" text-anchor="middle" font-size="10.5" fill="#475569">incitecek hoş</text>\n  <text x="218" y="178" text-anchor="middle" font-size="10.5" fill="#475569">olmayan isim takmak.</text>\n  <rect x="289" y="60" width="122" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. SÛ-İ ZAN</text>\n  <text x="350" y="112" text-anchor="middle" font-size="11" fill="#334155">(Kötü Düşünce)</text>\n  <text x="350" y="142" text-anchor="middle" font-size="10.5" fill="#475569">Kesin bilgi olmadan</text>\n  <text x="350" y="160" text-anchor="middle" font-size="10.5" fill="#475569">önyargı ve kuruntu</text>\n  <text x="350" y="178" text-anchor="middle" font-size="10.5" fill="#475569">ile suçlamak.</text>\n  <rect x="421" y="60" width="122" height="175" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="482" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">4. TECESSÜS</text>\n  <text x="482" y="112" text-anchor="middle" font-size="11" fill="#334155">(Gizliyi Araştırma)</text>\n  <text x="482" y="142" text-anchor="middle" font-size="10.5" fill="#475569">Başkalarının özel</text>\n  <text x="482" y="160" text-anchor="middle" font-size="10.5" fill="#475569">hayatını ve gizli</text>\n  <text x="482" y="178" text-anchor="middle" font-size="10.5" fill="#475569">kusurlarını eşelemek.</text>\n  <rect x="553" y="60" width="122" height="175" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="614" y="88" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">5. GIYBET</text>\n  <text x="614" y="112" text-anchor="middle" font-size="11" fill="#334155">(Arkadan Konuşma)</text>\n  <text x="614" y="142" text-anchor="middle" font-size="10.5" fill="#475569">Bir kimsenin yüzüne</text>\n  <text x="614" y="160" text-anchor="middle" font-size="10.5" fill="#475569">söylendiğinde hoşuna</text>\n  <text x="614" y="178" text-anchor="middle" font-size="10.5" fill="#475569">gitmeyeceği şeyi anmak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE GENEL ÖZETİ: KUR\'AN-I KERİM\'İ TANIYALIM</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kur\'an-ı Kerim\'in Güzel İsimleri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• el-Hüdâ (الهُدَى): Doğru yolu gösteren rehber</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• el-Furkan (الفُرْقَان): Hak ile batılı ayıran</text>\n  <text x="55" y="156" font-size="11.5" fill="#334155">• en-Nûr (النُّور): Gönülleri ve akılları aydınlatan</text>\n  <text x="55" y="180" font-size="11.5" fill="#334155">• eş-Şifâ (الشِّفَاء): Kalplere manevi şifa veren</text>\n  <text x="55" y="204" font-size="11.5" fill="#334155">• ez-Zikir (الذِّكْر): Düşündüren ve öğüt veren</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Kur\'an\'ın Ana Konuları ve Takva</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• İnanç (İman), İbadet, Ahlak, Muamelat, Kıssalar</text>\n  <text x="380" y="138" font-size="12" font-weight="bold" fill="#854d0e">Hucurât Suresi 13. Ayet Mesajı:</text>\n  <text x="380" y="160" font-size="11.5" fill="#334155">"Şüphesiz Allah katında en değerli olanınız,</text>\n  <text x="380" y="180" font-size="11.5" fill="#334155">O\'na karşı gelmekten en çok sakınanınızdır</text>\n  <text x="380" y="200" font-size="11.5" font-weight="bold" fill="#15803d">(en takvalı olanınızdır)."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
